import hashlib
import hmac
import time
import threading
import os
from dataclasses import dataclass, field
from typing import Dict, Optional
import secrets

# Secure session management with token rotation

SESSION_TIMEOUT = 3600  # 1 hour
ROTATION_WINDOW = 30    # 30 second grace period for old tokens
MAX_SESSIONS_PER_USER = 5
TOKEN_LENGTH = 32

@dataclass
class Session:
    user_id: str
    token_hash: str
    created_at: float
    last_active: float
    prev_token_hash: Optional[str] = None
    prev_token_expires: float = 0.0
    rotation_count: int = 0
    is_invalidated: bool = False

class SessionStore:
    def __init__(self, secret_key: bytes):
        self._secret = secret_key
        self._sessions: Dict[str, Session] = {}
        self._user_sessions: Dict[str, list] = {}
        self._lock = threading.RLock()

    def _hash_token(self, token: str) -> str:
        return hmac.new(self._secret, token.encode('utf-8'), hashlib.sha256).hexdigest()

    def _generate_token(self) -> str:
        return secrets.token_urlsafe(TOKEN_LENGTH)

    def _get_session_by_token_hash(self, token_hash: str) -> Optional[Session]:
        for sid, session in self._sessions.items():
            if session.token_hash == token_hash:
                return session
        return None

    def create_session(self, user_id: str) -> Optional[str]:
        with self._lock:
            # Enforce max sessions per user
            if user_id in self._user_sessions:
                active = [s for s in self._user_sessions[user_id] 
                         if not self._sessions[s].is_invalidated]
                if len(active) >= MAX_SESSIONS_PER_USER:
                    return None

            token = self._generate_token()
            token_hash = self._hash_token(token)
            session_id = secrets.token_hex(16)
            now = time.time()

            session = Session(
                user_id=user_id,
                token_hash=token_hash,
                created_at=now,
                last_active=now
            )

            self._sessions[session_id] = session
            if user_id not in self._user_sessions:
                self._user_sessions[user_id] = []
            self._user_sessions[user_id].append(session_id)

            return token

    def validate_and_rotate(self, token: str) -> Optional[str]:
        """Validate a session token. If valid, rotate it and return new token.
        Old token remains valid for ROTATION_WINDOW seconds."""
        token_hash = self._hash_token(token)
        now = time.time()

        with self._lock:
            session = None
            session_id = None

            # Check current tokens
            for sid, s in self._sessions.items():
                if s.is_invalidated:
                    continue
                if hmac.compare_digest(s.token_hash, token_hash):
                    session = s
                    session_id = sid
                    break

            # Check previous tokens within grace window
            if session is None:
                for sid, s in self._sessions.items():
                    if s.is_invalidated:
                        continue
                    if s.prev_token_hash and hmac.compare_digest(s.prev_token_hash, token_hash):
                        # Grace period check - strict expiration
                        if now >= s.prev_token_expires:
                            continue
                        session = s
                        session_id = sid
                        break

            if session is None:
                return None

            # Check session timeout
            if now - session.created_at > SESSION_TIMEOUT:
                session.is_invalidated = True
                return None

            # Perform rotation
            new_token = self._generate_token()
            new_token_hash = self._hash_token(new_token)

            session.prev_token_hash = session.token_hash
            session.prev_token_expires = now + ROTATION_WINDOW
            session.token_hash = new_token_hash
            session.last_active = now
            session.rotation_count += 1

            return new_token

    def validate_only(self, token: str) -> Optional[str]:
        """Validate token without rotation. Returns user_id if valid."""
        token_hash = self._hash_token(token)
        now = time.time()

        with self._lock:
            for sid, s in self._sessions.items():
                if s.is_invalidated:
                    continue

                # Check current token
                if hmac.compare_digest(s.token_hash, token_hash):
                    if now - s.created_at > SESSION_TIMEOUT:
                        s.is_invalidated = True
                        return None
                    s.last_active = now
                    return s.user_id

                # Check previous token in grace window
                if s.prev_token_hash and hmac.compare_digest(s.prev_token_hash, token_hash):
                    if now >= s.prev_token_expires:
                        continue
                    if now - s.created_at > SESSION_TIMEOUT:
                        s.is_invalidated = True
                        return None
                    s.last_active = now
                    return s.user_id

            return None

    def invalidate_session(self, token: str) -> bool:
        """Invalidate a session by its current token."""
        token_hash = self._hash_token(token)

        with self._lock:
            for sid, s in self._sessions.items():
                if hmac.compare_digest(s.token_hash, token_hash):
                    s.is_invalidated = True
                    s.prev_token_hash = None
                    return True
            return False

    def invalidate_all_user_sessions(self, user_id: str) -> int:
        """Invalidate all sessions for a user. Returns count invalidated."""
        count = 0
        with self._lock:
            if user_id in self._user_sessions:
                for sid in self._user_sessions[user_id]:
                    if not self._sessions[sid].is_invalidated:
                        self._sessions[sid].is_invalidated = True
                        self._sessions[sid].prev_token_hash = None
                        count += 1
        return count

    def cleanup_expired(self) -> int:
        """Remove expired sessions from store."""
        now = time.time()
        to_remove = []

        with self._lock:
            for sid, s in self._sessions.items():
                if s.is_invalidated or (now - s.created_at > SESSION_TIMEOUT * 2):
                    to_remove.append(sid)

            for sid in to_remove:
                session = self._sessions.pop(sid)
                if session.user_id in self._user_sessions:
                    self._user_sessions[session.user_id] = [
                        s for s in self._user_sessions[session.user_id] if s != sid
                    ]

        return len(to_remove)


def create_app_session_store() -> SessionStore:
    secret = os.environ.get('SESSION_SECRET', '').encode('utf-8')
    if len(secret) < 32:
        secret = secrets.token_bytes(64)
    return SessionStore(secret)
